ROWS = [
dict(id="T075", d="DYN", t="Absolute continuity of Bernoulli convolutions at transcendental parameters",
 s="For every transcendental λ ∈ (1/2, 1), the Bernoulli convolution ν_λ (the law of Σ_{n≥0} ±λ^n with independent fair signs) is absolutely continuous.",
 c="It is the form of Erdős's problem that the 2026 Salem counterexamples (T026, retired) leave untouched.",
 src="P. Erdős, On a family of symmetric Bernoulli convolutions, Amer. J. Math. 61 (1939); P. P. Varjú, Recent progress on Bernoulli convolutions, in European Congress of Mathematics (EMS, 2018) 847–867",
 why="The model case of self-similar measures with overlaps; the recent dimension theory (Hochman, Shmerkin, Varjú) settles dimension but not absolute continuity.",
 st="Dimension one for every transcendental λ (Varjú, arXiv:1810.08905, Ann. Math. 2019); absolutely continuous for almost every λ (Solomyak 1995) and outside a set of Hausdorff dimension zero (Shmerkin, arXiv:1303.3992, GAFA 2014); for algebraic λ close to 1 in terms of the Mahler measure (Varjú, arXiv:1602.00261, JAMS 2019; Kittle, arXiv:2103.12684, Ann. Sci. ENS). Kittle–Kogler (arXiv:2610.10511, Oct 2026, not yet refereed) prove the exact overlaps conjecture and its entropy version on the line, which gives the dimension of every Bernoulli convolution; absolute continuity is not covered. Pisot reciprocals (Erdős 1939) and quartic Salem reciprocals (Cheng–Fang–Ma–Zhang, arXiv:2610.12072, Oct 2026) give singular measures. Open."),
dict(id="T076", d="RMT", t="Random band matrices in dimensions two and three",
 s="For random band matrices indexed by the box {1, …, L}^d, with independent centred entries (up to symmetry) in a fixed symmetry class, H_xy = 0 unless |x − y| ≤ W, and a regular variance profile, bulk eigenvectors are delocalized with Wigner–Dyson local statistics when W ≫ √(log L) in d = 2, and for every W ≥ W_0 with W_0 fixed in d = 3; in d = 2 the localization length is of order exp(cW²).",
 src="Y. V. Fyodorov and A. D. Mirlin, Scaling properties of localization in random band matrices: a σ-model approach, Phys. Rev. Lett. 67 (1991); P. Bourgade, Random band matrices, Proc. ICM 2018",
 why="Band matrices in d ≥ 2 interpolate between Wigner matrices and the Anderson model; d = 3 delocalization at bounded W is the matrix analogue of the extended-states conjecture (T009).",
 st="d = 1 is settled (T035, retired). Delocalization when W is a power of L: d ≥ 7 (Xu–Yang–Yau–Yin, arXiv:2207.14533: quantum unique ergodicity for complex Gaussian entries when W ≥ L^ε, after Yang–Yau–Yin, arXiv:2104.12048, in d ≥ 8), d = 2 with W ≥ N^c (Dubova–Yang–Yau–Yin, arXiv:2503.07606) and d ≥ 3 with W ≥ N^c (Dubova–Yang–Yau–Yin, arXiv:2507.20274). In d = 2, Lai–Yang (arXiv:2609.24426) reach W ≥ (log N)^7 with localization length at least exp(W^{1/7}). The predicted exp(cW²) scale in d = 2 and bounded W in d = 3 are open."),
dict(id="T077", d="IPS", t="Coexistence in the two-type Richardson model only at equal rates",
 s="In the two-type Richardson model on Z^d, d ≥ 2 (two infections spread from single sites at rates λ_1 and λ_2, and each site is taken by the first type to reach it), both types grow without bound with positive probability only when λ_1 = λ_2.",
 src="O. Häggström and R. Pemantle, First passage percolation and a model for competing spatial growth, J. Appl. Probab. 35 (1998); O. Häggström and R. Pemantle, Absence of mutual unbounded growth for almost all parameter values in the two-type Richardson model, Stochastic Process. Appl. 90 (2000)",
 why="The basic model of competing spatial growth; the answer depends on how one first-passage front can surround another, which ties it to the shape and geodesics of first-passage percolation.",
 st="Coexistence with equal rates: d = 2 (Häggström–Pemantle 1998), every d ≥ 2 (Garet–Marchand 2005; Hoffman 2005). For unequal rates coexistence has probability zero for all but countably many ratios (Häggström–Pemantle 2000). Open for every given ratio other than 1."),
dict(id="T078", x="SOLVED (claimed, unrefereed), 14 Nov 2026: the OpenAI math release preprint 'Spontaneous magnetization in the quantum Heisenberg ferromagnet' (24 Sep 2026, Thm 1.1) claims a translation-invariant zero-field KMS state with magnetization at least S/4 for every d >= 3 and every spin S at low positive temperature. AI-written and unrefereed; this records the claim, not a check of the proof. Replacement row to be screened.", d="SM", t="Long-range order in the three-dimensional quantum Heisenberg ferromagnet",
 s="The spin-S quantum Heisenberg ferromagnet on Z^d, d ≥ 3 (H = −Σ_{x∼y} S_x · S_y), has spontaneous magnetization at low positive temperature, for every S ∈ {1/2, 1, 3/2, …}.",
 src="F. J. Dyson, E. H. Lieb and B. Simon, Phase transitions in quantum spin systems with isotropic and nonisotropic interactions, J. Stat. Phys. 18 (1978); B. Simon, Fifteen problems in mathematical physics, in Perspectives in Mathematics: Anniversary of Oberwolfach 1984 (Birkhäuser, 1984)",
 why="The textbook case of spontaneous breaking of a continuous symmetry in quantum statistical mechanics; reflection positivity, which handles the classical model and the antiferromagnet, fails for the quantum ferromagnet. For S = 1/2 it is the cycle-weighted relative of Tóth's interchange problem (T012).",
 st="Proved for the classical Heisenberg model (Fröhlich–Simon–Spencer 1976) and for quantum antiferromagnets (Dyson–Lieb–Simon 1978, d ≥ 3 and S ≥ 1; Kennedy–Lieb–Shastry 1988, S = 1/2 on Z^3). For the ferromagnet: low-temperature free energy given by spin-wave theory (bounds by Conlon–Solovej 1991; the spin-wave asymptotics in d = 3 by Correggi–Giuliani–Seiringer, arXiv:1312.7873, CMP 2015); order on the complete graph and on trees through the interchange representation (Tóth; Björnberg, arXiv:1512.06986; Hammond, arXiv:1202.1322). Open on Z^3."),
dict(id="T079", d="SM", t="The continuum limit of lattice Yang–Mills theory in three and four dimensions",
 s="Lattice Yang–Mills theory with a compact non-abelian gauge group (for example SU(2)) on εZ^d, d = 3 or 4, with the coupling tuned as ε → 0, has a nontrivial continuum limit satisfying the Osterwalder–Schrader axioms; in d = 4 the limit has a mass gap.",
 c="The d = 4 statement with a mass gap is the Clay Millennium problem; its probabilistic content is the construction of the limiting random field.",
 src="A. Jaffe and E. Witten, Quantum Yang–Mills theory, Clay Mathematics Institute Millennium Problem description (2000); S. Chatterjee, Yang–Mills for probabilists, in Probability and Analysis in Interacting Physical Systems (Springer, 2019)",
 why="Constructing a four-dimensional non-abelian gauge theory is the central open problem of constructive quantum field theory; confinement on the lattice (T011) is its companion.",
 st="Solved in two dimensions (Gross–King–Sengupta; Driver; Sengupta; Lévy). Balaban's renormalization-group programme gives ultraviolet stability in finite volume for d = 3, 4 (surveyed in Chatterjee, arXiv:1803.01950). Stochastic quantization of Yang–Mills locally in time in d = 2 (Chandra–Chevyrev–Hairer–Shen, arXiv:2006.04987, Publ. IHÉS 2022) and of Yang–Mills–Higgs in d = 3 (same authors, arXiv:2201.03487, Invent. Math. 2024). Open."),
dict(id="T080", d="SM", t="The freezing transition of hard spheres",
 s="The hard-sphere gas in R^d, d ≥ 2, has a phase transition as the density increases: close enough to close packing its infinite-volume Gibbs measures break translational symmetry when d ≥ 3, and have long-range orientational order when d = 2 (hard disks).",
 src="B. J. Alder and T. E. Wainwright, Phase transition for a hard sphere system, J. Chem. Phys. 27 (1957); E. P. Bernard and W. Krauth, Two-step melting in two dimensions: first-order liquid–hexatic transition, Phys. Rev. Lett. 107 (2011)",
 why="Freezing of hard spheres is the simplest entropy-driven phase transition, seen in every simulation since 1957 and in colloids, and nothing comparable is proved for any continuum particle system at positive temperature.",
 st="Hard-core lattice gases order at high activity (Dobrushin 1968). In the continuum: uniqueness at low density by cluster expansion; hard disks cannot break translational symmetry (Richthammer, arXiv:0706.3637, CMP 2007); the densest packings are known in d = 3 (Hales 2005) and in d = 8, 24 (Viazovska, arXiv:1603.04246; Cohn–Kumar–Miller–Radchenko–Viazovska, arXiv:1603.06518; Ann. of Math. 185 (2017)). No phase transition has been proved for hard spheres or hard disks in the continuum. See also T044."),
dict(id="T081", d="SM", t="The liquid–vapour transition for continuum particles with pair interactions",
 s="Classical point particles in R^d, d ≥ 2, interacting through a fixed stable, translation-invariant pair potential with a short-range repulsion and a finite-range attraction (of Lennard-Jones type) have a liquid–vapour transition: for some temperature and chemical potential there are two infinite-volume Gibbs measures with different densities.",
 c="The class of potentials must be fixed; the known proofs add Kac scaling, a four-body repulsion or an attraction tied to a fixed partition of space.",
 src="J. L. Lebowitz, A. Mazel and E. Presutti, Liquid–vapor phase transitions for systems with finite-range interactions, J. Stat. Phys. 94 (1999); D. Ruelle, Existence of a phase transition in a continuous classical system, Phys. Rev. Lett. 27 (1971)",
 why="Liquid–gas coexistence is the oldest phase transition in physics (van der Waals 1873) and is still unproved for any finite-range pair potential in the continuum.",
 st="Proved with Kac potentials at small scale parameter and a four-body repulsion (Lebowitz–Mazel–Presutti, arXiv:cond-mat/9809145, J. Stat. Phys. 1999), for the Widom–Rowlinson model (Ruelle 1971; a stochastic-geometric proof by Chayes–Chayes–Kotecký, CMP 1995) and the continuum Potts model (Georgii–Häggström, CMP 1996). With pair interactions only, He–Jauslin–Lebowitz–Peled (arXiv:2510.24825) prove it at a fixed small Kac parameter in a boxed model whose attraction follows a fixed partition into cubes, so not translation invariant. Open for translation-invariant pair potentials."),
dict(id="T082", d="DYN", t="The Boltzmann–Sinai ergodic hypothesis for hard balls",
 s="N ≥ 2 hard balls of radius r on the flat torus T^d, d ≥ 2, moving freely and colliding elastically, form an ergodic (indeed Bernoulli) system on each component of the energy surface once total momentum and centre of mass are fixed, for every N and every admissible r.",
 src="Ya. G. Sinai, On the foundations of the ergodic hypothesis for a dynamical system of statistical mechanics, Soviet Math. Dokl. 4 (1963); D. Szász (ed.), Hard Ball Systems and the Lorentz Gas (Springer, 2000)",
 why="Boltzmann's ergodic hypothesis in its cleanest mathematical form; it is the justification of equilibrium statistical mechanics for the hard-sphere gas.",
 st="Proved: Simányi (arXiv:1205.0061, 2012; published 2013), after N = 2 (Sinai 1970), N = 3 (Krámli–Simányi–Szász 1991) and almost every choice of masses or radii (Simányi–Szász 1999; Simányi 2003, 2004, 2009).",
 x="SOLVED: Simányi (arXiv:1205.0061, 2012; published 2013) completes the proof for every N ≥ 2, every d ≥ 2 and every admissible radius; the survey arXiv:1512.08272 treats the hypothesis as proved. Read from the arXiv abstract 14 Oct; flagged by the w672 audit."),
dict(id="T083", d="DYN", t="Pointwise convergence of multiple ergodic averages",
 s="For a measure-preserving system (X, μ, T), k ≥ 3 and f_1, …, f_k ∈ L^∞(μ), the averages (1/N) Σ_{n<N} f_1(T^n x) f_2(T^{2n} x) ⋯ f_k(T^{kn} x) converge for μ-almost every x.",
 c="The commuting version, with f_i(T_i^n x) for commuting T_1, …, T_k, is the natural extension.",
 src="H. Furstenberg, Recurrence in Ergodic Theory and Combinatorial Number Theory (Princeton, 1981); J. Bourgain, Double recurrence and almost sure convergence, J. Reine Angew. Math. 404 (1990)",
 why="Norm convergence (Host–Kra 2005; Ziegler 2007) underlies the ergodic route to Szemerédi's theorem, but almost-everywhere convergence beyond two terms has resisted every method.",
 st="k = 2 (Bourgain 1990). Norm convergence for every k (Host–Kra 2005; Ziegler 2007) and for commuting transformations (Tao, arXiv:0707.1117, ETDS 2008). Pointwise results for nilsystems (Leibman 2005) and distal systems (Huang–Shao–Ye, arXiv:1406.5930), and for the bilinear averages f(T^n x) g(T^{P(n)} x) with deg P ≥ 2 (Krause–Mirek–Tao, arXiv:2008.00857, Ann. Math. 2022). Open for k = 3. Update, 14 Nov 2026: the OpenAI math release (github.com/openai/math; AI-written, unrefereed) has 'Pointwise Multiple Ergodic Averages for Mixing Transformations' (4 Oct 2026), which claims convergence for every k under mixing, and in its Lemma 2.5 general triple convergence; arbitrary systems with k >= 3 remain open."),
dict(id="T084", d="COMB", t="Negative correlation for uniform forests and for random-cluster measures with q < 1",
 s="For every finite graph G and distinct edges e, f, a uniformly random spanning forest (acyclic subgraph) F of G satisfies P(e ∈ F, f ∈ F) ≤ P(e ∈ F) P(f ∈ F). More generally, random-cluster measures with 0 < q ≤ 1, whose limits include uniform forests and uniform connected subgraphs, are conjectured to have this pairwise negative correlation; negative association is a stronger, separate conjecture.",
 src="R. Pemantle, Towards a theory of negative dependence, J. Math. Phys. 41 (2000); G. R. Grimmett and S. N. Winkler, Negative association in uniform forests and connected graphs, Random Structures Algorithms 24 (2004)",
 why="Spanning trees are negatively correlated (Kirchhoff; Feder–Mihail), and forests are the next case; negative association would give the q < 1 random-cluster model a theory comparable to the FKG theory for q ≥ 1.",
 st="Spanning trees and balanced matroids (Feder–Mihail 1992); checked by computer on small graphs (Grimmett–Winkler 2004); a bound with factor 2, P(e, f ∈ F) ≤ 2 P(e ∈ F) P(f ∈ F), for random bases of any matroid by Hodge theory for matroids (Huh–Schröter–Wang, arXiv:1806.02675; stated for bases, so it does not cover forests). Pairwise negative correlation is proved for uniform forests of every complete graph K_n, n ≥ 2 (Gupta, arXiv:2609.26134); for the weighted forest measure on any graph at large enough fugacity, provided one of the two leading coefficients of the Rayleigh difference is nonzero, and for the q < 1 random-cluster model on K_n with all edge weights at least 2, or all equal and at least 1 (Çiçeksiz–Ravichandran, arXiv:2610.00549); and for 0 ≤ q < 1 on high-degree regular graphs satisfying a two-scale edge-isoperimetric condition, where the pairwise conjecture is also shown equivalent to its restriction to regular graphs of diverging degree (Tang–Zhang, arXiv:2609.11578). Open for uniform forests on general graphs."),
dict(id="T085", d="RW", t="Random Cayley graphs of the symmetric group are expanders",
 s="There is ε > 0 such that, for two independent uniformly random permutations σ, τ ∈ S_n, the Cayley graph of the group they generate, with generators σ^{±1}, τ^{±1}, is an ε-expander with probability tending to one as n → ∞.",
 src="A. Lubotzky, Expander graphs in pure and applied mathematics, Bull. Amer. Math. Soc. 49 (2012), arXiv:1105.2389; A. Lubotzky, Discrete Groups, Expanding Graphs and Invariant Measures (Birkhäuser, 1994)",
 why="Random generators give expanders for finite simple groups of Lie type of bounded rank (Breuillard–Green–Guralnick–Tao 2015); the symmetric group is the main case left, and it governs how fast a random walk with random generators mixes.",
 st="S_n has bounded-size expanding generating sets (Kassabov 2007). For random generators: diameter O(n²(log n)^c) and mixing time O(n³(log n)^c) with high probability (Helfgott–Seress–Zuk, arXiv:1311.6742); their spectral-gap bound, the best known, still tends to zero with n. Open.",
 c="Two random permutations generate A_n or S_n with probability tending to one (Dixon 1969). Both are even with probability 1/4, and then the Cayley graph of S_n is disconnected, so the statement must be made on the generated group (w672 audit, 14 Oct, T085_parity_counterexample.md)."),
dict(id="T086", d="BM", t="Small ball probabilities for the Brownian sheet in dimension three and higher",
 s="For the Brownian sheet W on [0, 1]^d with d ≥ 3, −log P(sup_{t ∈ [0,1]^d} |W(t)| ≤ ε) is of order ε^{−2} (log(1/ε))^{2d−1} as ε → 0.",
 c="The exponent 2d − 1 is the conjectured one; it matches Talagrand's d = 2 answer.",
 src="M. Talagrand, The small ball problem for the Brownian sheet, Ann. Probab. 22 (1994); D. Bilyk, M. Lacey and A. Vagharshakyan, On the small ball inequality in all dimensions, J. Funct. Anal. 254 (2008)",
 why="It is tied to the small ball inequality for hyperbolic Haar sums and so to lower bounds for the discrepancy of point sets in dimension three and above, a central open problem of irregularities of distribution.",
 st="d = 2: ε^{−2}(log 1/ε)^3 (Talagrand 1994). For d ≥ 3 an upper bound with exponent 2d − 1 (Dunker–Kühn–Lifshits–Linde 1998) and a lower bound with exponent 2d − 2, improved by a small power of the logarithm (Bilyk–Lacey, arXiv:math/0609815, Duke Math. J. 2008, in d = 3; Bilyk–Lacey–Vagharshakyan, arXiv:0705.4619, J. Funct. Anal. 2008, in d ≥ 4). Open."),
]
